import itertools
from pysat.card import CardEnc, EncType
from pysat.solvers import Glucose4
from pysat.formula import IDPool

n_golfers = 32
n_groups = 8
n_weeks = 6
group_size = 4

vpool = IDPool()

# Variable: x[w][p][g] = 1 if golfer p is in group g in week w
var_map = {}

def get_var(w, p, g):
    key = (w, p, g)
    if key not in var_map:
        var_map[key] = vpool.top
        vpool.id()
    return var_map[key]

clauses = []

# Each golfer in exactly one group per week
for w in range(n_weeks):
    for p in range(n_golfers):
        # At least one group
        clause = [get_var(w, p, g) for g in range(n_groups)]
        clauses.append(clause)
        # At most one group: pairwise
        for g1, g2 in itertools.combinations(range(n_groups), 2):
            clauses.append([-get_var(w, p, g1), -get_var(w, p, g2)])

# Each group has exactly 4 golfers per week
for w in range(n_weeks):
    for g in range(n_groups):
        lits = [get_var(w, p, g) for p in range(n_golfers)]
        c = CardEnc.equals(lits, group_size, vpool=vpool, encoding=EncType.seqcounter)
        clauses.extend(c.clauses)

# No pair repeats
for p1, p2 in itertools.combinations(range(n_golfers), 2):
    aux_vars = []
    for w in range(n_weeks):
        aux = vpool.top
        vpool.id()
        aux_vars.append(aux)
        # aux <-> (group[p1] == group[p2])
        # (x[p1][g] AND x[p2][g]) -> aux
        for g in range(n_groups):
            clauses.append([-get_var(w, p1, g), -get_var(w, p2, g), aux])
        # aux -> (x[p1][g] <-> x[p2][g])
        for g in range(n_groups):
            clauses.append([-aux, -get_var(w, p1, g), get_var(w, p2, g)])
            clauses.append([-aux, get_var(w, p1, g), -get_var(w, p2, g)])

    # At most one week
    c = CardEnc.atmost(aux_vars, 1, vpool=vpool, encoding=EncType.seqcounter)
    clauses.extend(c.clauses)

print(f"Total variables: {vpool.top}")
print(f"Total clauses: {len(clauses)}")

# Solve
solver = Glucose4()
for cl in clauses:
    solver.add_clause(cl)

print("Solving...")
result = solver.solve()
print("Result:", result)

if result:
    model = solver.get_model()
    solution = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            for g in range(n_groups):
                var = get_var(w, p, g)
                if model[var-1] > 0:
                    solution.append(g)
                    break
    print("Solution:", solution)
    # Verify
    for w in range(n_weeks):
        counts = [0]*n_groups
        for p in range(n_golfers):
            counts[solution[w*32+p]] += 1
        print(f"Week {w} group sizes: {counts}")
    pair_weeks = {}
    ok = True
    for p1, p2 in itertools.combinations(range(n_golfers), 2):
        for w in range(n_weeks):
            if solution[w*32+p1] == solution[w*32+p2]:
                if (p1,p2) in pair_weeks:
                    print(f"ERROR: pair ({p1},{p2}) together in weeks {pair_weeks[(p1,p2)]} and {w}")
                    ok = False
                pair_weeks[(p1,p2)] = w
    if ok:
        print("All constraints satisfied!")
else:
    print("UNSAT")

